spec.expr:
(
  (node_filesystem_size_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"}
   - node_filesystem_avail_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"})
  / node_filesystem_size_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"}
) * 100

node_load1{server=~"$server", job="$job"}
/ on(server) group_left
count by (server) (
  sum without (mode, instance) (
    node_cpu_seconds_total{server=~"$server", job="$job", mode="idle"}
  )
)

